```go
func processAll(ctx context.Context, jobs []Job) ([]Result, error) {
    results := make(chan Result)
    errs := make(chan error)
    for _, j := range jobs {
        go func(j Job) {
            r, err := handle(ctx, j)
            if err != nil {
                errs <- err
                return
            }
            results <- r
        }(j)
    }
    var out []Result
    for range jobs {
        select {
        case r := <-results:
            out = append(out, r)
        case err := <-errs:
            return nil, err
        }
    }
    return out, nil
}
```

