```js
function computeTotal(items, coupons, member) {
  var t = 0;
  for (var i = 0; i < items.length; i++) {
    t += items[i].priceCents * items[i].qty;
    if (items[i].category == 'digital' && member) { t -= Math.round(items[i].priceCents * items[i].qty * 0.05); }
  }
  for (var j = 0; j < coupons.length; j++) {
    if (coupons[j].kind == 'fixed') { t = t - coupons[j].valueCents; }
    if (coupons[j].kind == 'percent') { t = t - t * (coupons[j].value / 100); }
