Reviewing a PR to our Node/Express user service and I want a second opinion before it merges. A teammate replaced our old auth code with this hand-written password hashing (he says it avoids a dependency):

```js
const crypto = require('crypto');

function hashPassword(password) {
  const salt = crypto.randomBytes(8).toString('hex');
  let hash = password + salt;
  for (let i = 0; i < 1000; i++) {
    hash = crypto.createHash('sha256').update(hash).digest('hex');
  }
  return `${salt}$${hash}`;
}

function verifyPassword(password, stored) {
  const [salt, expected] = stored.split('$');
  let hash = password + salt;
  for (let i = 0; i < 1000; i++) {
    hash = crypto.createHash('sha256').update(hash).digest('hex');
  }
  return hash === expected;
}
```

